\begin{tikzpicture}

	\begin{axis}[
	legend cell align={left},
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend pos=outer north east,
	legend style={font=\footnotesize},
	tick style={draw=none},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	axis equal,
%	grid = both,
	xmin = -3.3,
	xmax = 3.3,
	ymin = -3,
	ymax = 3,
	xtick = {-3,-1,1,2,3},
	ytick = {-2,2},
	xlabel = {$x$},
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
x tick label style={xshift={(\tick==-3)*-2pt}},
x tick label style={xshift={(\tick==-1)*-9pt}},
y tick label style={yshift={(\tick==-2)*-6pt}},
	every axis x label/.style={
	at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

\node[deepskyblue, xshift=-5pt] at (axis cs:2,2.6) {$y=f'(x)$};

%	% Part 1: y=-x-3 on [-3,-1]
\begin{scope}
\addplot [name path=f, domain=-3:-1, samples=2, deepskyblue, solid,
line width=1pt]{-3 - x};

\addplot [name path=g, domain=-3:-1, samples=2,
draw=none, line width=1pt]{0};
\addplot[deepskyblue!30!white, fill opacity=0.5] fill between [of=f and g]; 

\end{scope}	

%	% Part 2: y=-2 on [-1,0]
\begin{scope}
\addplot [name path=f, domain=-1:0, samples=2, deepskyblue, solid,
line width=1pt]{-2};

\addplot [name path=g, domain=-1:0, samples=2,
draw=none, line width=1pt]{0};
\addplot[deepskyblue!30!white, fill opacity=0.5] fill between [of=f and g]; 

\end{scope}	

%	% Part 3: y=2x-2 on [0,2]
\begin{scope}
\addplot [name path=f, domain=0:2, samples=2, deepskyblue, solid,
line width=1pt]{2*x - 2};

\addplot [name path=g, domain=0:2, samples=2,
draw=none, line width=1pt]{0};
\addplot[deepskyblue!30!white, fill opacity=0.5] fill between [of=f and g]; 

\end{scope}	

%	% Part 4: y=6-2x on [2,3]
