\addplot [name path=f, domain=2:3, samples=2, deepskyblue, solid,
line width=1pt]{6 - 2*x};

\addplot [name path=g, domain=2:3, samples=2,
draw=none, line width=1pt]{0};
\addplot[deepskyblue!30!white, fill opacity=0.5] fill between [of=f and g]; 
\end{scope}	

% Area Labels
