\draw[dashed, line width=0.6pt, opacity=0.5] (axis cs:2,0) -- (axis cs:2,2);
\draw[dashed, line width=0.6pt, opacity=0.5] (axis cs:0,2) -- (axis cs:2,2);

\end{axis}
